            expect(elements.length).toBe(0);
        });

        it('should select element from selection', function () {
            this.el.innerHTML = 'lorem <i>ipsum</i> dolor';
            selectElementContents(this.el.querySelector('i').firstChild);
            var elements = MediumEditor.selection.getSelectedElements(document);

            expect(elements.length).toBe(1);
            expect(elements[0].nodeName.toLowerCase()).toBe('i');
            expect(elements[0].innerHTML).toBe('ipsum');
        });

        it('should select first element when selection is global (ie: all the editor)', function () {
            this.el.innerHTML = 'lorem <i>ipsum</i> dolor';
            selectElementContents(this.el);
            var elements = MediumEditor.selection.getSelectedElements(document);

            expect(elements.length).toBe(1);
            expect(elements[0].nodeName.toLowerCase()).toBe('i');
            expect(elements[0].innerHTML).toBe('ipsum');
        });
    });

    describe('getSelectedParentElement', function () {
        it('should return null on bad range', function () {
            expect(MediumEditor.selection.getSelectedParentElement(null)).toBe(null);
            expect(MediumEditor.selection.getSelectedParentElement(false)).toBe(null);
        });

        it('should select the document', function () {
            this.el.innerHTML = '<p>lorem <i>ipsum</i> dolor <span>hello</span> <b>you</b> </p>';
            var range = document.createRange(),
                sel = window.getSelection(),
                element;

            range.setStart(document, 0);
            range.setEnd(this.el.querySelector('b').firstChild, 2);

            sel.removeAllRanges();
            sel.addRange(range);

            element = MediumEditor.selection.getSelectedParentElement(range);

            expect(element).toBe(document);
        });
    });

    describe('selectionContainsContent', function () {
        it('should return true for non-empty text', function () {
            this.el.innerHTML = '<p>this is<span> </span>text</p>';
            selectElementContents(this.el.querySelector('p'));

            expect(MediumEditor.selection.selectionContainsContent(document)).toBe(true);
        });

        it('should return false for white-space only selections', function () {
            this.el.innerHTML = '<p>this is<span> </span>text</p>';
            selectElementContents(this.el.querySelector('span'));

            expect(MediumEditor.selection.selectionContainsContent(document)).toBe(false);
        });

        it('should return true for image with link selections', function () {
            this.el.innerHTML = '<p>this is <a href="#"><img src="../demo/img/medium-editor.jpg" /></a> image test</p>';
            selectElementContents(this.el.querySelector('a'));

            expect(MediumEditor.selection.selectionContainsContent(document)).toBe(true);
        });
    });

    describe('clearSelection', function () {
        it('should clear the selection and set the caret to the start of the prior range when specified', function () {
            this.el.innerHTML = '<p>this is<span> </span>text</p>';
            selectElementContents(this.el.querySelector('p'));
            var selectionStart = document.getSelection().anchorOffset;

            MediumEditor.selection.clearSelection(document, true);
            expect(document.getSelection().focusOffset).toBe(selectionStart);

            var newSelectionEnd = document.getSelection().focusOffset;
            expect(newSelectionEnd).toBe(selectionStart);
        });

        it('should clear the selection and set the caret to the end of the prior range by default', function () {
            this.el.innerHTML = '<p>this is<span> </span>text</p>';
            selectElementContents(this.el.querySelector('p'));
            var selectionEnd = document.getSelection().focusOffset;

            MediumEditor.selection.clearSelection(document);
            expect(document.getSelection().anchorOffset).toBe(selectionEnd);

            var newSelectionStart = document.getSelection().anchorOffset;
            expect(newSelectionStart).toBe(selectionEnd);
        });
    });
});

import { cleanup_api_response } from '@/utils/cleanup-api-response'
import {
  CodeAtCursorItem,
  TextItem,
  extract_workspace_and_path
} from '../../response-parser'

const extract_path_and_position = (
  line: string
): { path: string; line: number; character: number } | null => {
  const path_pos_regex = /###\s+Code at cursor:\s+`?([^`]+)`?\s+\((\d+):(\d+)\)/

  const match = line.match(path_pos_regex)

  if (match) {
    const path = match[1].trim()
    const line_num_str = match[2]
    const char_num_str = match[3]

    if (path && line_num_str && char_num_str) {
      return {
        path,
        line: parseInt(line_num_str, 10),
        character: parseInt(char_num_str, 10)
      }
    }
  }
  return null
}

export const parse_code_at_cursor = (params: {
  response: string
  is_single_root_folder_workspace: boolean
}): (CodeAtCursorItem | TextItem)[] | null => {
  const lines = params.response.split('\n')
  let code_block_start_index = -1
  let code_block_end_index = -1

  for (let i = 0; i < lines.length; i++) {
    if (lines[i].trim().startsWith('```')) {
      code_block_start_index = i
      for (let j = i + 1; j < lines.length; j++) {
        if (lines[j].trim().startsWith('```')) {
          code_block_end_index = j
          break
        }
      }
      break
    }
  }

  if (code_block_start_index == -1) {
    return null
  }

  if (code_block_end_index == -1) {
    code_block_end_index = lines.length - 1
  }

  let header_index = -1
  let completion_info = null

  for (let k = code_block_start_index - 1; k >= 0; k--) {
    if (lines[k].trim() == '') continue
    const info = extract_path_and_position(lines[k])
    if (info) {
      header_index = k
      completion_info = info
    }
    break
  }

  if (!completion_info) {
    return null
  }

  const results: (CodeAtCursorItem | TextItem)[] = []
  const text_before = lines.slice(0, header_index).join('\n').trim()
  if (text_before) {
    results.push({ type: 'text', content: text_before })
  }

  const { workspace_name, relative_path } = extract_workspace_and_path({
    raw_file_path: completion_info.path,
    is_single_root_folder_workspace: params.is_single_root_folder_workspace
  })

  const content_lines = lines.slice(
    code_block_start_index + 1,
    code_block_end_index
  )

  results.push({
    type: 'code-at-cursor',
    file_path: relative_path,
    content: cleanup_api_response({ content: content_lines.join('\n') }),
    line: completion_info.line,
    character: completion_info.character,
    workspace_name
  })

  const text_after = lines
    .slice(code_block_end_index + 1)
    .join('\n')
    .trim()
  if (text_after) {
    results.push({ type: 'text', content: text_after })
  }

  return results
}

import * as fs from 'fs'
import * as path from 'path'
import * as vscode from 'vscode'
import { create_safe_path } from '@/utils/path-sanitizer'
import { show_ghost_text } from './utils/show-ghost-text'
import { normalize_path } from '@/utils/normalize-path'
import { WorkspaceProvider } from '@/context/providers/workspace/workspace-provider'
import { OpenEditorsProvider } from '@/context/providers/open-editors/open-editors-provider'
import { CommitMessageDetails } from '@/utils/commit-message-details'
import { perform_code_at_cursor } from './utils/perform-code-at-cursor'
import { WebSocketManager } from '@/services/websocket-manager'

export const code_at_cursor_commands = (params: {
  workspace_provider: WorkspaceProvider
  open_editors_provider: OpenEditorsProvider
  extension_context: vscode.ExtensionContext
  websocket_manager: WebSocketManager
}) => {
  return [
    vscode.commands.registerCommand(
      'codeWebChat.internal.applyCodeAtCursor',
      async (args: {
        file_path: string
        workspace_name?: string
        line: number
        character: number
        content: string
      }) => {
        const workspace_map = new Map<string, string>()
        vscode.workspace.workspaceFolders?.forEach((folder) => {
          workspace_map.set(folder.name, folder.uri.fsPath)
        })
        const default_workspace =
          vscode.workspace.workspaceFolders?.[0]?.uri.fsPath
        if (!default_workspace) {
          vscode.window.showErrorMessage('No workspace folder open')
          return
        }

        let workspace_root = default_workspace
        if (args.workspace_name && workspace_map.has(args.workspace_name)) {
          workspace_root = workspace_map.get(args.workspace_name)!
        }

        const safe_path = create_safe_path(workspace_root, args.file_path)
        if (!safe_path || !fs.existsSync(safe_path)) {
          vscode.window.showErrorMessage(`File not found: ${args.file_path}`)
          return
        }

        const document = await vscode.workspace.openTextDocument(safe_path)
        const editor = await vscode.window.showTextDocument(document)

        const line_index = args.line - 1
        const char_index = args.character - 1

        if (
          line_index < 0 ||
          char_index < 0 ||
          line_index >= document.lineCount ||
          char_index > document.lineAt(line_index).text.length
        ) {
          vscode.window.showErrorMessage(
            `Invalid position in file: ${args.file_path}`
          )
          return
        }

        const position = new vscode.Position(line_index, char_index)

        if (
          editor.selection.active.line !== position.line ||
          editor.selection.active.character !== position.character
        ) {
          editor.selection = new vscode.Selection(position, position)
          editor.revealRange(
            new vscode.Range(position, position),
            vscode.TextEditorRevealType.InCenterIfOutsideViewport
          )
        }

        const decoded_completion = args.content

        const selected_files: string[] = []
        const checked_files = params.workspace_provider.get_checked_files()
        for (const file of checked_files) {
          const file_workspace_root =
            params.workspace_provider.get_workspace_root_for_file(file)
          if (file_workspace_root === workspace_root) {
            const relative_path = normalize_path(
              path.relative(workspace_root, file)
            )
            selected_files.push(relative_path)
          }
        }

        await show_ghost_text({
          editor,
          position,
          ghost_text: decoded_completion,
          command: {
            title: 'Code at Cursor Accepted',
            command: 'codeWebChat.internal.codeAtCursorAccepted',
            arguments: [
              {
                workspace_root,
                prompt: '',
                file_path: safe_path,
                selected_files
              }
            ]
          }
        })
      }
    ),
    vscode.commands.registerCommand(
      'codeWebChat.internal.codeAtCursorAccepted',
      async (args: {
        workspace_root: string
        prompt?: string
        file_path: string
        selected_files: string[]
      }) => {
        CommitMessageDetails.add({
          extension_context: params.extension_context,
          workspace_root: args.workspace_root,
          prompt: args.prompt,
          files: [args.file_path],
          selected_files: args.selected_files
        })
      }
    ),
    vscode.commands.registerCommand('codeWebChat.codeAtCursor', async () =>
      perform_code_at_cursor({
        workspace_provider: params.workspace_provider,
        open_editors_provider: params.open_editors_provider,
        extension_context: params.extension_context,
        websocket_manager: params.websocket_manager,
        with_completion_instructions: false,
        show_quick_pick: false
      })
    ),
    vscode.commands.registerCommand(
      'codeWebChat.codeAtCursorWithInstructions',
      async () =>
        perform_code_at_cursor({
          workspace_provider: params.workspace_provider,
          open_editors_provider: params.open_editors_provider,
          extension_context: params.extension_context,
          websocket_manager: params.websocket_manager,
          with_completion_instructions: true,
          show_quick_pick: false
        })
    ),
    vscode.commands.registerCommand('codeWebChat.codeAtCursorUsing', async () =>
      perform_code_at_cursor({
        workspace_provider: params.workspace_provider,
        open_editors_provider: params.open_editors_provider,
        extension_context: params.extension_context,
        websocket_manager: params.websocket_manager,
        with_completion_instructions: false,
        show_quick_pick: true
      })
    ),
    vscode.commands.registerCommand(
      'codeWebChat.codeAtCursorWithInstructionsUsing',
      async () =>
        perform_code_at_cursor({
          workspace_provider: params.workspace_provider,
          open_editors_provider: params.open_editors_provider,
          extension_context: params.extension_context,
          websocket_manager: params.websocket_manager,
          with_completion_instructions: true,
          show_quick_pick: true
        })
    )
  ]
}
